1	/**
2	 * Known AI model profiles with context window sizes and metadata.
3	 * Used to auto-detect the active model and set the correct budget.
4	 *
5	 * ⚠️  DO NOT EDIT BY HAND — generated from models.json
6	 *     Run: npm run generate-models
7	 */
8	
9	export interface ModelProfile {
10	  id: string;
11	  label: string;
12	  provider: 'anthropic' | 'openai' | 'google' | 'other';
13	  contextWindow: number;   // tokens
14	  maxOutput: number;        // max output tokens
15	  rotThreshold: number;     // chat turns before context rot risk
16	  inputCostPerMTok: number;  // $ per million input tokens
17	  outputCostPerMTok: number; // $ per million output tokens
18	}
19	
20	/**
21	 * Built-in model profiles.
22	 * Context windows and rot thresholds based on published benchmarks.
23	 */
24	export const MODEL_PROFILES: ModelProfile[] = [
25	  // Anthropic
26	  { id: 'claude-opus-4.6'  , label: 'Claude Opus 4.6'  , provider: 'anthropic'  , contextWindow:  200000, maxOutput:  32000, rotThreshold: 40, inputCostPerMTok: 5.00 , outputCostPerMTok: 25.00 },
27	  { id: 'claude-opus-4.5'  , label: 'Claude Opus 4.5'  , provider: 'anthropic'  , contextWindow:  200000, maxOutput:  32000, rotThreshold: 35, inputCostPerMTok: 5.00 , outputCostPerMTok: 25.00 },
28	  { id: 'claude-sonnet-4.6', label: 'Claude Sonnet 4.6', provider: 'anthropic'  , contextWindow:  200000, maxOutput:  16000, rotThreshold: 25, inputCostPerMTok: 3.00 , outputCostPerMTok: 15.00 },
29	  { id: 'claude-sonnet-4.5', label: 'Claude Sonnet 4.5', provider: 'anthropic'  , contextWindow:  200000, maxOutput:  16000, rotThreshold: 20, inputCostPerMTok: 3.00 , outputCostPerMTok: 15.00 },
30	  { id: 'claude-sonnet-4'  , label: 'Claude Sonnet 4'  , provider: 'anthropic'  , contextWindow:  200000, maxOutput:  16000, rotThreshold: 18, inputCostPerMTok: 3.00 , outputCostPerMTok: 15.00 },
31	  { id: 'claude-haiku-4.5' , label: 'Claude Haiku 4.5' , provider: 'anthropic'  , contextWindow:  200000, maxOutput:  16000, rotThreshold: 15, inputCostPerMTok: 1.00 , outputCostPerMTok: 5.00  },
32	
33	  // OpenAI
34	  { id: 'gpt-5.4'          , label: 'GPT-5.4'          , provider: 'openai'     , contextWindow: 1000000, maxOutput: 128000, rotThreshold: 35, inputCostPerMTok: 2.50 , outputCostPerMTok: 10.00 },
35	  { id: 'gpt-5.4-mini'     , label: 'GPT-5.4 Mini'     , provider: 'openai'     , contextWindow:  400000, maxOutput: 128000, rotThreshold: 22, inputCostPerMTok: 0.40 , outputCostPerMTok: 1.60  },
36	  { id: 'gpt-5.2-codex'    , label: 'GPT-5.2 Codex'    , provider: 'openai'     , contextWindow:  400000, maxOutput: 128000, rotThreshold: 28, inputCostPerMTok: 2.50 , outputCostPerMTok: 10.00 },
37	  { id: 'gpt-5.1-codex'    , label: 'GPT-5.1 Codex'    , provider: 'openai'     , contextWindow:  400000, maxOutput: 128000, rotThreshold: 25, inputCostPerMTok: 2.50 , outputCostPerMTok: 10.00 },
38	  { id: 'gpt-4.1'          , label: 'GPT-4.1'          , provider: 'openai'     , contextWindow: 1047576, maxOutput:  32768, rotThreshold: 20, inputCostPerMTok: 2.00 , outputCostPerMTok: 8.00  },
39	  { id: 'o3'               , label: 'o3'               , provider: 'openai'     , contextWindow:  200000, maxOutput: 100000, rotThreshold: 20, inputCostPerMTok: 2.00 , outputCostPerMTok: 8.00  },
40	  { id: 'o4-mini'          , label: 'o4-mini'          , provider: 'openai'     , contextWindow:  200000, maxOutput: 100000, rotThreshold: 15, inputCostPerMTok: 1.10 , outputCostPerMTok: 4.40  },
41	
42	  // Google
43	  { id: 'gemini-3.1-pro'   , label: 'Gemini 3.1 Pro'   , provider: 'google'     , contextWindow: 1048576, maxOutput:  65536, rotThreshold: 32, inputCostPerMTok: 1.25 , outputCostPerMTok: 5.00  },
44	  { id: 'gemini-3-pro'     , label: 'Gemini 3 Pro'     , provider: 'google'     , contextWindow: 1048576, maxOutput:  65536, rotThreshold: 30, inputCostPerMTok: 1.25 , outputCostPerMTok: 5.00  },
45	  { id: 'gemini-3-flash'   , label: 'Gemini 3 Flash'   , provider: 'google'     , contextWindow: 1048576, maxOutput:  65536, rotThreshold: 25, inputCostPerMTok: 0.075, outputCostPerMTok: 0.30  },
46	  { id: 'gemini-2.5-pro'   , label: 'Gemini 2.5 Pro'   , provider: 'google'     , contextWindow: 1048576, maxOutput:  65536, rotThreshold: 22, inputCostPerMTok: 1.25 , outputCostPerMTok: 5.00  },
47	];
48	
49	/** Default model when nothing is detected */
50	export const DEFAULT_MODEL_ID = 'claude-opus-4.6';
51	
52	/**
53	 * Try to find a matching model profile by partial ID or label match.
54	 * Priority: exact id → exact label → startsWith → contains.
55	 */
56	export function findModel(query: string): ModelProfile | undefined {
57	  const q = query.toLowerCase().replace(/[^a-z0-9.]/g, '');
58	  if (!q) return undefined;
59	
60	  // 1. Exact match on normalized id
61	  const exact = MODEL_PROFILES.find(m =>
62	    m.id.toLowerCase().replace(/[^a-z0-9.]/g, '') === q
63	  );
64	  if (exact) return exact;
65	
66	  // 2. Exact match on normalized label
67	  const labelExact = MODEL_PROFILES.find(m =>
68	    m.label.toLowerCase().replace(/[^a-z0-9.]/g, '') === q
69	  );
70	  if (labelExact) return labelExact;
71	
72	  // 3. Starts-with on id or label
73	  const startsWith = MODEL_PROFILES.find(m => {
74	    const mid = m.id.toLowerCase().replace(/[^a-z0-9.]/g, '');
75	    const mlabel = m.label.toLowerCase().replace(/[^a-z0-9.]/g, '');
76	    return mid.startsWith(q) || mlabel.startsWith(q);
77	  });
78	  if (startsWith) return startsWith;
79	
80	  // 4. Contains match (fallback)
81	  return MODEL_PROFILES.find(m => {
82	    const mid = m.id.toLowerCase().replace(/[^a-z0-9.]/g, '');
83	    const mlabel = m.label.toLowerCase().replace(/[^a-z0-9.]/g, '');
84	    return mid.includes(q) || mlabel.includes(q) || q.includes(mid);
85	  });
86	}
87	
88	/**
89	 * Get a model profile by exact ID, falling back to default.
90	 */
91	export function getModel(id: string): ModelProfile {
92	  return MODEL_PROFILES.find(m => m.id === id)
93	    || MODEL_PROFILES.find(m => m.id === DEFAULT_MODEL_ID)!;
94	}
