143	    const mid = m.id.toLowerCase().replace(/[^a-z0-9.]/g, '');
144	    const mlabel = m.label.toLowerCase().replace(/[^a-z0-9.]/g, '');
145	    return mid.includes(q) || mlabel.includes(q) || q.includes(mid);
