150	 * Get a model profile by exact ID, falling back to default.
151	 */
152	export function getModel(id: string): ModelProfile {
153	  return MODEL_PROFILES.find(m => m.id === id)
154	    || MODEL_PROFILES.find(m => m.id === DEFAULT_MODEL_ID)!;
155	}
156	`;
