1	import * as vscode from 'vscode';
2	import { TabInfo, ContextSnapshot, TurnSnapshot, SessionSummary, CostEstimate } from './types';
3	import { TabRelevanceScorer } from './tabRelevanceScorer';
4	import { TokenBudgetEstimator } from './tokenBudgetEstimator';
5	import { TokenizerService } from './tokenizerService';
6	import { ModelProfile, MODEL_PROFILES, DEFAULT_MODEL_ID, getModel, findModel } from './modelProfiles';
7	import { SessionLogger } from './sessionLogger';
8	
9	const PINNED_FILES_KEY = 'tokalator.pinnedFiles';
10	const SELECTED_MODEL_KEY = 'tokalator.selectedModel';
11	const SESSION_KEY = 'tokalator.lastSession';
12	
13	/**
14	 * Core engine that tracks all editor state and produces real-time ContextSnapshots.
15	 *
16	 * Subscribes to:
17	 *  - Active editor changes
18	 *  - Tab open/close events
19	 *  - Text document changes
20	 *  - Diagnostics changes
21	 *
22	 * Emits:
23	 *  - onDidUpdateSnapshot: fires with a fresh ContextSnapshot after each state change
24	 */
25	export class ContextMonitor implements vscode.Disposable {
26	
27	  private readonly _onDidUpdateSnapshot = new vscode.EventEmitter<ContextSnapshot>();
28	  readonly onDidUpdateSnapshot = this._onDidUpdateSnapshot.event;
29	
30	  private readonly scorer = new TabRelevanceScorer();
31	  private readonly tokenizer = new TokenizerService();
32	  private readonly estimator = new TokenBudgetEstimator(this.tokenizer);
33	
34	  private pinnedFiles = new Set<string>();
35	  private chatTurnCount = 0;
36	  private turnHistory: TurnSnapshot[] = [];
37	  private lastEditTimestamps = new Map<string, number>();
38	  private disposables: vscode.Disposable[] = [];
39	  private refreshTimer: ReturnType<typeof setInterval> | undefined;
40	
41	  private latestSnapshot: ContextSnapshot | null = null;
42	  private debounceTimer: ReturnType<typeof setTimeout> | undefined;
43	  private isRefreshing = false;
44	  private pendingRefresh = false;
45	
46	  private activeModel: ModelProfile;
47	  private workspaceFileTokens = 0;
48	  private workspaceFileCount = 0;
49	
50	  // Session tracking
51	  private peakTokens = 0;
52	  private peakPercent = 0;
53	  private fileEditCounts = new Map<string, number>();
54	
55	  // Opt-in session logger for research studies
56	  private sessionLogger: SessionLogger | null = null;
57	
58	  constructor(private readonly workspaceState?: vscode.Memento) {
59	    // Load persisted pinned files (normalize URIs for consistent matching)
60	    if (workspaceState) {
61	      const saved = workspaceState.get<string[]>(PINNED_FILES_KEY, []);
62	      this.pinnedFiles = new Set(saved.map(u => this.normalizeUri(u)));
63	    }
64	
65	    // Load persisted model selection
66	    const savedModelId = workspaceState?.get<string>(SELECTED_MODEL_KEY, DEFAULT_MODEL_ID) || DEFAULT_MODEL_ID;
67	    this.activeModel = getModel(savedModelId);
68	    this.estimator.setProvider(this.activeModel.provider);
69	
70	    // Scan workspace files on startup
71	    this.scanWorkspaceFiles();
72	
73	    // Debounced refresh to avoid perf issues from rapid event firing
74	    const debouncedRefresh = () => {
75	      if (this.debounceTimer) { clearTimeout(this.debounceTimer); }
76	      this.debounceTimer = setTimeout(() => this.refresh(), 300);
77	    };
78	
79	    // Subscribe to VS Code events
80	    this.disposables.push(
81	      vscode.window.onDidChangeActiveTextEditor(() => debouncedRefresh()),
82	      vscode.window.onDidChangeTextEditorSelection(() => debouncedRefresh()),
83	      vscode.window.tabGroups.onDidChangeTabs(() => debouncedRefresh()),
84	      vscode.workspace.onDidChangeTextDocument(e => {
85	        const uri = e.document.uri.toString();
86	        this.lastEditTimestamps.set(uri, Date.now());
87	        this.fileEditCounts.set(uri, (this.fileEditCounts.get(uri) || 0) + 1);
88	        debouncedRefresh();
89	      }),
90	      vscode.workspace.onDidOpenTextDocument(() => debouncedRefresh()),
91	      // Clean up caches when documents close (memory leak fix)
92	      vscode.workspace.onDidCloseTextDocument(doc => {
93	        const uri = doc.uri.toString();
94	        this.lastEditTimestamps.delete(uri);
95	        this.estimator.clearCacheFor(uri);
96	        debouncedRefresh();
97	      }),
98	      vscode.languages.onDidChangeDiagnostics(() => debouncedRefresh()),
99	      // Sync model when settings change (skip if already on that model to avoid loop)
100	      vscode.workspace.onDidChangeConfiguration(e => {
101	        if (e.affectsConfiguration('tokalator.model')) {
102	          const cfg = vscode.workspace.getConfiguration('tokalator');
103	          const modelId = cfg.get<string>('model', DEFAULT_MODEL_ID);
104	          if (modelId !== this.activeModel.id) {
105	            this.setModel(modelId);
106	          }
107	        }
108	      }),
109	      // Sync when VS Code's available chat model set changes (e.g. provider rollout,
110	      // deprecation, or user installs a new Copilot extension)
111	      vscode.lm.onDidChangeChatModels(() => {
112	        void this.syncModelFromAvailableLMs();
113	      }),
114	    );
115	
116	    // Periodic refresh for time-based scoring (recency decay)
117	    const config = vscode.workspace.getConfiguration('tokalator');
118	    const interval = config.get<number>('autoRefreshInterval', 2000);
119	    this.refreshTimer = setInterval(() => this.refresh(), interval);
120	
121	    // Opt-in session logging for research studies
122	    if (config.get<boolean>('enableSessionLogging', false)) {
123	      this.sessionLogger = new SessionLogger();
124	      this.sessionLogger.startSession(this.activeModel.id);
125	    }
126	
127	    // Initial snapshot
128	    this.refresh();
129	  }
130	
131	  /**
132	   * Build a fresh snapshot and emit it.
133	   */
134	  async refresh(): Promise<void> {
135	    if (this.isRefreshing) {
136	      // Queue one pending refresh so the final state after rapid switching is captured
137	      this.pendingRefresh = true;
138	      return;
139	    }
140	    this.isRefreshing = true;
141	    this.pendingRefresh = false;
142	    try {
143	      const snapshot = await this.buildSnapshot();
144	      this.latestSnapshot = snapshot;
145	      this._onDidUpdateSnapshot.fire(snapshot);
146	
147	      // Log snapshot to session logger if enabled
148	      if (this.sessionLogger) {
149	        this.sessionLogger.logSnapshot(snapshot);
150	      }
151	    } finally {
152	      this.isRefreshing = false;
153	      // If events arrived while we were refreshing, run one more pass
154	      if (this.pendingRefresh) {
155	        this.pendingRefresh = false;
156	        void this.refresh();
157	      }
158	    }
159	  }
160	
161	  /**
162	   * Get the most recent snapshot without triggering a refresh.
163	   */
164	  getLatestSnapshot(): ContextSnapshot | null {
165	    return this.latestSnapshot;
166	  }
167	
168	  /**
169	   * Normalize a URI string for consistent Set matching.
170	   */
171	  private normalizeUri(uri: string): string {
172	    try {
173	      return vscode.Uri.parse(uri).toString();
174	    } catch {
175	      return uri;
176	    }
177	  }
178	
179	  /**
180	   * Pin a file URI so it's always scored as maximum relevance.
181	   */
182	  pinFile(uri: string): void {
183	    this.pinnedFiles.add(this.normalizeUri(uri));
184	    this.persistPins();
185	    this.refresh();
186	  }
187	
188	  /**
189	   * Unpin a file.
190	   */
191	  unpinFile(uri: string): void {
192	    this.pinnedFiles.delete(this.normalizeUri(uri));
193	    this.persistPins();
194	    this.refresh();
195	  }
196	
197	  /**
198	   * Clear all pins.
199	   */
200	  clearPins(): void {
201	    this.pinnedFiles.clear();
202	    this.persistPins();
203	    this.refresh();
204	  }
205	
206	  /**
207	   * Persist pinned files to workspace state.
208	   */
209	  private persistPins(): void {
210	    if (this.workspaceState) {
211	      this.workspaceState.update(PINNED_FILES_KEY, Array.from(this.pinnedFiles));
212	    }
213	  }
214	
215	  /**
216	   * Increment the conversation turn counter and capture a turn snapshot.
217	   * Only call this for actual user interactions, not status checks.
218	   */
219	  async incrementChatTurns(): Promise<void> {
220	    this.chatTurnCount++;
221	
222	    // Capture a turn snapshot for compaction tracking
223	    const snapshot = this.latestSnapshot;
224	    if (snapshot) {
225	      const fileTokens = snapshot.tabs.reduce((s, t) => s + t.estimatedTokens, 0);
226	      const overheadTokens = snapshot.totalEstimatedTokens - fileTokens;
227	      this.turnHistory.push({
228	        turn: this.chatTurnCount,
229	        timestamp: Date.now(),
230	        inputTokens: snapshot.totalEstimatedTokens,
231	        outputReserved: this.activeModel.maxOutput,
232	        fileTokens,
233	        overheadTokens,
234	        tabCount: snapshot.tabs.length,
235	        pinnedCount: this.pinnedFiles.size,
236	      });
237	    }
238	
239	    this.refresh();
240	  }
241	
242	  /**
243	   * Estimate the token cost of the *next* chat turn before sending.
244	   * This gives users a preview of what will be consumed.
245	   */
246	  async previewNextTurn(): Promise<{
247	    currentInput: number;
248	    nextTurnEstimate: number;
249	    conversationGrowth: number;
250	    outputReserved: number;
251	    remainingCapacity: number;
252	    percentAfterTurn: number;
253	    windowCapacity: number;
254	    warning: string | null;
255	  }> {
256	    await this.refresh();
257	    const snapshot = this.latestSnapshot;
258	    if (!snapshot) {
259	      return {
260	        currentInput: 0, nextTurnEstimate: 0, conversationGrowth: 800,
261	        outputReserved: this.activeModel.maxOutput, remainingCapacity: this.activeModel.contextWindow,
262	        percentAfterTurn: 0, windowCapacity: this.activeModel.contextWindow, warning: null,
263	      };
264	    }
265	
266	    // Each turn adds ~800 tokens (user message + assistant response)
267	    const perTurnCost = 800;
268	    const nextTurnInput = snapshot.totalEstimatedTokens + perTurnCost;
269	    const nextPercent = Math.min((nextTurnInput / snapshot.windowCapacity) * 100, 100);
270	    const remaining = Math.max(snapshot.windowCapacity - nextTurnInput - this.activeModel.maxOutput, 0);
271	
272	    let warning: string | null = null;
273	    if (nextPercent >= 90) {
274	      warning = 'Next turn will push you past 90% — high risk of context overflow';
275	    } else if (nextPercent >= 75) {
276	      warning = 'Approaching context limit — consider closing tabs or resetting';
277	    }
278	
279	    // Check if next turn crosses the rot threshold
280	    if (this.chatTurnCount + 1 >= this.activeModel.rotThreshold) {
281	      const rotMsg = `Turn ${this.chatTurnCount + 1} will cross context rot threshold (${this.activeModel.rotThreshold})`;
282	      warning = warning ? `${warning}. ${rotMsg}` : rotMsg;
283	    }
284	
285	    return {
286	      currentInput: snapshot.totalEstimatedTokens,
287	      nextTurnEstimate: nextTurnInput,
288	      conversationGrowth: perTurnCost,
289	      outputReserved: this.activeModel.maxOutput,
290	      remainingCapacity: remaining,
291	      percentAfterTurn: nextPercent,
292	      windowCapacity: snapshot.windowCapacity,
293	      warning,
294	    };
295	  }
296	
297	  /**
298	   * Reset conversation turn counter and clear turn history.
299	   */
300	  resetChatTurns(): void {
301	    this.chatTurnCount = 0;
302	    this.turnHistory = [];
303	    this.refresh();
304	  }
305	
306	  /**
307	   * Get current chat turn count.
308	   */
309	  getChatTurnCount(): number {
310	    return this.chatTurnCount;
311	  }
312	
313	  /**
314	   * Get the per-turn snapshot history for compaction analysis.
315	   */
316	  getTurnHistory(): TurnSnapshot[] {
317	    return [...this.turnHistory];
318	  }
319	
320	  /**
321	   * Close tabs below relevance threshold.
322	   * Returns the list of closed tab labels.
323	   */
324	  async optimizeTabs(): Promise<string[]> {
325	    const config = vscode.workspace.getConfiguration('tokalator');
326	    const threshold = config.get<number>('relevanceThreshold', 0.3);
327	
328	    const snapshot = await this.buildSnapshot();
329	    const toClose = snapshot.tabs.filter(
330	      t => t.relevanceScore < threshold && !t.isActive && !t.isPinned
331	    );
332	
333	    const closed: string[] = [];
334	    for (const tab of toClose) {
335	      const allTabs = vscode.window.tabGroups.all.flatMap(g => g.tabs);
336	      const vsTab = allTabs.find(t => {
337	        if (t.input instanceof vscode.TabInputText) {
338	          return t.input.uri.toString() === tab.uri.toString();
339	        }
340	        return false;
341	      });
342	      if (vsTab) {
343	        await vscode.window.tabGroups.close(vsTab);
344	        closed.push(tab.label);
345	      }
346	    }
347	
348	    // Log optimize action to session logger if enabled
349	    if (this.sessionLogger && closed.length > 0) {
350	      this.sessionLogger.logOptimize(snapshot.tabs.length, snapshot.totalEstimatedTokens, closed.length);
351	    }
352	
353	    return closed;
354	  }
355	
356	  /**
357	   * Build the full context snapshot.
358	   */
359	  private async buildSnapshot(): Promise<ContextSnapshot> {
360	    const config = vscode.workspace.getConfiguration('tokalator');
361	    // Use windowSize setting as override only when it differs from the default (1,000,000)
362	    const configWindowSize = config.get<number>('windowSize', 1000000);
363	    const windowCapacity = configWindowSize !== 1000000 ? configWindowSize : this.activeModel.contextWindow;
364	    const rotWarning = this.activeModel.rotThreshold;
365	
366	    // 1. Gather all open tabs
367	    let tabs = this.gatherTabs();
368	
369	    // 2. Estimate tokens for each tab
370	    tabs = await this.estimator.estimateAllTabs(tabs);
371	
372	    // 3. Score relevance
373	    tabs = this.scorer.scoreAll(tabs, vscode.window.activeTextEditor);
374	
375	    // 4. Sort by relevance (highest first)
376	    tabs.sort((a, b) => b.relevanceScore - a.relevanceScore);
377	
378	    // 5. Gather diagnostics summary
379	    const diagnosticsSummary = this.gatherDiagnosticsSummary();
380	
381	    // 6. Count instruction files in workspace
382	    const instructionFiles = await this.countInstructionFiles();
383	
384	    // 7. Compute budget
385	    const budget = this.estimator.computeBudget(
386	      tabs,
387	      this.chatTurnCount,
388	      instructionFiles,
389	      windowCapacity
390	    );
391	
392	    // Track peak usage for session summary
393	    if (budget.used > this.peakTokens) {
394	      this.peakTokens = budget.used;
395	      this.peakPercent = budget.percent;
396	    }
397	
398	    // 8. Determine budget level (simplified from percentage)
399	    let budgetLevel: 'low' | 'medium' | 'high';
400	    if (budget.percent > 85) {
401	      budgetLevel = 'high';
402	    } else if (budget.percent > 60) {
403	      budgetLevel = 'medium';
404	    } else {
405	      budgetLevel = 'low';
406	    }
407	
408	    // 9. Determine health and reasons
409	    const healthReasons: string[] = [];
410	    let contextHealth: ContextSnapshot['contextHealth'] = 'healthy';
411	
412	    if (budgetLevel === 'high') {
413	      contextHealth = 'critical';
414	      healthReasons.push('Token budget is high — context overflow risk');
415	    } else if (budgetLevel === 'medium') {
416	      contextHealth = 'warning';
417	      healthReasons.push('Token budget is medium — consider closing unused tabs');
418	    }
419	
420	    if (this.chatTurnCount >= rotWarning) {
421	      contextHealth = contextHealth === 'critical' ? 'critical' : 'warning';
422	      healthReasons.push(`${this.chatTurnCount} chat turns — context may be stale`);
423	    }
424	
425	    const distractors = tabs.filter(t => {
426	      const threshold = config.get<number>('relevanceThreshold', 0.3);
427	      return t.relevanceScore < threshold && !t.isActive && !t.isPinned;
428	    });
429	    if (distractors.length > 3) {
430	      contextHealth = contextHealth === 'critical' ? 'critical' : 'warning';
431	      healthReasons.push(`${distractors.length} low-relevance tabs open`);
432	    }
433	
434	    if (healthReasons.length === 0) {
435	      healthReasons.push('Token budget looks good');
436	    }
437	
438	    const activeFile = tabs.find(t => t.isActive) || null;
439	
440	    // 10. Estimate cost for this turn
441	    const inputTokens = budget.used;
442	    const outputTokens = this.activeModel.maxOutput;
443	    const inputCost = (inputTokens / 1_000_000) * this.activeModel.inputCostPerMTok;
444	    const outputCost = (outputTokens / 1_000_000) * this.activeModel.outputCostPerMTok;
445	    const costEstimate: CostEstimate = {
446	      inputTokens,
447	      outputTokens,
448	      inputCost,
449	      outputCost,
450	      totalCost: inputCost + outputCost,
451	      inputCostPerMTok: this.activeModel.inputCostPerMTok,
452	      outputCostPerMTok: this.activeModel.outputCostPerMTok,
453	    };
454	
455	    return {
456	      timestamp: Date.now(),
457	      activeFile,
458	      tabs,
459	      pinnedFiles: this.pinnedFiles,
460	      totalEstimatedTokens: budget.used,
461	      windowCapacity,
462	      usagePercent: budget.percent,
463	      budgetLevel,
464	      diagnosticsSummary,
465	      chatTurnCount: this.chatTurnCount,
466	      contextHealth,
467	      healthReasons,
468	      modelId: this.activeModel.id,
469	      modelLabel: this.activeModel.label,
470	      workspaceFileCount: this.workspaceFileCount,
471	      workspaceFileTokens: this.workspaceFileTokens,
472	      tokenizerType: this.tokenizer.getTokenizerType(this.activeModel.provider),
473	      tokenizerLabel: this.tokenizer.getTokenizerLabel(this.activeModel.provider),
474	      turnHistory: [...this.turnHistory],
475	      budgetBreakdown: budget.breakdown,
476	      costEstimate,
477	    };
478	  }
479	
480	  /**
481	   * Gather TabInfo from all open tab groups.
482	   */
483	  private gatherTabs(): TabInfo[] {
484	    const tabs: TabInfo[] = [];
485	    const seenUris = new Set<string>();
486	    const workspaceFolders = vscode.workspace.workspaceFolders || [];
487	
488	    for (const group of vscode.window.tabGroups.all) {
489	      for (const tab of group.tabs) {
490	        if (!(tab.input instanceof vscode.TabInputText)) { continue; }
491	
492	        const uri = tab.input.uri;
493	        const uriKey = uri.toString();
494	
495	        // Skip duplicate URIs (same file open in split panes)
496	        if (seenUris.has(uriKey)) { continue; }
497	        seenUris.add(uriKey);
498	
499	        const fsPath = uri.fsPath;
500	
501	        // Find the matching workspace folder for correct relative path in multi-root workspaces
502	        const matchingFolder = workspaceFolders.find(f => fsPath.startsWith(f.uri.fsPath));
503	        const relativePath = matchingFolder
504	          ? fsPath.replace(matchingFolder.uri.fsPath, '').replace(/^[/\\]/, '')
505	          : fsPath;
506	
507	        // Get language ID from open documents
508	        const openDoc = vscode.workspace.textDocuments.find(
509	          d => d.uri.toString() === uri.toString()
510	        );
511	        const languageId = openDoc?.languageId || this.guessLanguage(fsPath);
512	
513	        // Get diagnostics for this file
514	        const diagnostics = vscode.languages.getDiagnostics(uri);
515	        const diagnosticCount = diagnostics.length;
516	
517	        // Get last edit timestamp
518	        const lastEdit = this.lastEditTimestamps.get(uri.toString()) || 0;
519	
520	        tabs.push({
521	          uri,
522	          label: tab.label,
523	          languageId,
524	          relativePath,
525	          estimatedTokens: 0,   // filled later by estimator
526	          relevanceScore: 0,     // filled later by scorer
527	          relevanceReason: '',
528	          isActive: tab.isActive,
529	          isDirty: tab.isDirty,
530	          isPinned: this.pinnedFiles.has(uri.toString()),
531	          diagnosticCount,
532	          lastEditTimestamp: lastEdit,
533	        });
534	      }
535	    }
536	
537	    return tabs;
538	  }
539	
540	  /**
541	   * Aggregate diagnostics across all open files.
542	   */
543	  private gatherDiagnosticsSummary(): { errors: number; warnings: number; info: number } {
544	    const allDiags = vscode.languages.getDiagnostics();
545	    let errors = 0, warnings = 0, info = 0;
546	
547	    for (const [, diags] of allDiags) {
548	      for (const d of diags) {
549	        switch (d.severity) {
550	          case vscode.DiagnosticSeverity.Error: errors++; break;
551	          case vscode.DiagnosticSeverity.Warning: warnings++; break;
552	          default: info++; break;
553	        }
554	      }
555	    }
556	
557	    return { errors, warnings, info };
558	  }
559	
560	  /**
561	   * Count .instructions.md files in the workspace (they consume context budget).
562	   */
563	  private async countInstructionFiles(): Promise<number> {
564	    try {
565	      const exclude = '**/node_modules/**';
566	      const [instrFiles, copilotInstr, claudeMd, agentsMd, cursorRules] = await Promise.all([
567	        vscode.workspace.findFiles('**/*.instructions.md', exclude, 20),
568	        vscode.workspace.findFiles('.github/copilot-instructions.md', undefined, 1),
569	        vscode.workspace.findFiles('**/CLAUDE.md', exclude, 5),
570	        vscode.workspace.findFiles('**/AGENTS.md', exclude, 5),
571	        vscode.workspace.findFiles('**/.cursorrules', exclude, 5),
572	      ]);
573	      return instrFiles.length + copilotInstr.length + claudeMd.length + agentsMd.length + cursorRules.length;
574	    } catch {
575	      return 0;
576	    }
577	  }
578	
579	  /**
580	   * Guess language from file extension.
581	   */
582	  private guessLanguage(fsPath: string): string {
583	    const ext = fsPath.split('.').pop()?.toLowerCase() || '';
584	    const map: Record<string, string> = {
585	      ts: 'typescript', tsx: 'typescriptreact', js: 'javascript', jsx: 'javascriptreact',
586	      py: 'python', go: 'go', rs: 'rust', java: 'java', rb: 'ruby',
587	      md: 'markdown', json: 'json', yml: 'yaml', yaml: 'yaml',
588	      css: 'css', html: 'html', sh: 'shellscript', sql: 'sql',
589	    };
590	    return map[ext] || ext;
591	  }
592	
593	  /**
594	   * Called when vscode.lm.onDidChangeChatModels fires.
595	   * If the current model is no longer available, switches to the best known
596	   * alternative and notifies the user.
597	   */
598	  async syncModelFromAvailableLMs(): Promise<void> {
599	    const available = await vscode.lm.selectChatModels();
600	    if (!available.length) { return; }
601	
602	    const current = this.activeModel;
603	
604	    // Check if any available model maps to our current profile — still good
605	    const stillPresent = available.some(lm =>
606	      (findModel(lm.family) ?? findModel(lm.id) ?? findModel(lm.name))?.id === current.id
607	    );
608	    if (stillPresent) { return; }
609	
610	    // Current model gone — find the best available substitute
611	    for (const lm of available) {
612	      const match = findModel(lm.family) ?? findModel(lm.id) ?? findModel(lm.name);
613	      if (match) {
614	        await this.setModel(match.id);
615	        vscode.window.showInformationMessage(
616	          `Tokalator: "${current.label}" is no longer available. Switched to "${match.label}".`
617	        );
618	        return;
619	      }
620	    }
621	  }
622	
623	  /**
624	   * Set the active model and persist it.
625	   */
626	  async setModel(modelId: string): Promise<void> {
627	    this.activeModel = getModel(modelId);
628	    this.estimator.setProvider(this.activeModel.provider);
629	    if (this.workspaceState) {
630	      this.workspaceState.update(SELECTED_MODEL_KEY, modelId);
631	    }
632	    // Sync the VS Code setting so Settings UI / dashboard selector stay in sync
633	    const cfg = vscode.workspace.getConfiguration('tokalator');
634	    const currentSetting = cfg.get<string>('model');
635	    if (currentSetting !== modelId) {
636	      await cfg.update('model', modelId, vscode.ConfigurationTarget.Global);
637	    }
638	    // Rescan workspace with new tokenizer ratios, then refresh dashboard
639	    await this.scanWorkspaceFiles();
640	    await this.refresh();
641	  }
642	
643	  /**
644	   * Get the current active model.
645	   */
646	  getActiveModel(): ModelProfile {
647	    return this.activeModel;
648	  }
649	
650	  /**
651	   * Get all available models.
652	   */
653	  getModels(): ModelProfile[] {
654	    return MODEL_PROFILES;
655	  }
656	
657	  /**
658	   * Get the tokenizer service for direct token counting.
659	   */
660	  getTokenizer(): TokenizerService {
661	    return this.tokenizer;
662	  }
663	
664	  /**
665	   * Scan workspace files to estimate total project token count.
666	   * This runs once on startup and on workspace change.
667	   */
668	  private async scanWorkspaceFiles(): Promise<void> {
669	    try {
670	      const files = await vscode.workspace.findFiles(
671	        '**/*.{ts,tsx,js,jsx,py,go,rs,java,rb,md,json,yml,yaml,css,html,sh,sql,c,cpp,h,cs,swift,kt}',
672	        '{**/node_modules/**,**/dist/**,**/build/**,**/.next/**,**/vendor/**,**/.git/**}',
673	        5000
674	      );
675	      this.workspaceFileCount = files.length;
676	
677	      // Estimate total workspace tokens using provider-specific byte ratios
678	      let totalBytes = 0;
679	      for (const uri of files) {
680	        try {
681	          const stat = await vscode.workspace.fs.stat(uri);
682	          totalBytes += stat.size;
683	        } catch {
684	          // skip unreadable files
685	        }
686	      }
687	      this.workspaceFileTokens = this.tokenizer.estimateFromBytes(totalBytes, this.activeModel.provider);
688	    } catch {
689	      this.workspaceFileCount = 0;
690	      this.workspaceFileTokens = 0;
691	    }
692	  }
693	
694	  /**
695	   * Save a session summary to workspace state for next activation.
696	   */
697	  saveSessionSummary(): void {
698	    const snapshot = this.latestSnapshot;
699	    if (!snapshot || !this.workspaceState) return;
700	
701	    const topFiles = [...this.fileEditCounts.entries()]
702	      .sort((a, b) => b[1] - a[1])
703	      .slice(0, 5)
704	      .map(([uri]) => {
705	        try {
706	          return vscode.workspace.asRelativePath(vscode.Uri.parse(uri));
707	        } catch {
708	          return uri;
709	        }
710	      });
711	
712	    const summary: SessionSummary = {
713	      endedAt: new Date().toISOString(),
714	      modelId: this.activeModel.id,
715	      modelLabel: this.activeModel.label,
716	      totalTurns: this.chatTurnCount,
717	      peakTokens: this.peakTokens,
718	      peakPercent: this.peakPercent,
719	      tabCount: snapshot.tabs.length,
720	      pinnedCount: this.pinnedFiles.size,
721	      filesWorkedOn: topFiles,
722	      budgetLevel: snapshot.budgetLevel,
723	      healthStatus: snapshot.contextHealth,
724	    };
725	
726	    this.workspaceState.update(SESSION_KEY, summary);
727	  }
728	
729	  /**
730	   * Get last session summary (if any).
731	   */
732	  getLastSession(): SessionSummary | undefined {
733	    return this.workspaceState?.get<SessionSummary>(SESSION_KEY);
734	  }
735	
736	  dispose(): void {
737	    this.saveSessionSummary();
738	    if (this.sessionLogger) { this.sessionLogger.endSession(); }
739	    if (this.refreshTimer) { clearInterval(this.refreshTimer); }
740	    if (this.debounceTimer) { clearTimeout(this.debounceTimer); }
741	    this._onDidUpdateSnapshot.dispose();
742	    this.tokenizer.dispose();
743	    this.disposables.forEach(d => d.dispose());
744	  }
745	}
