\${(function() {
  if (!priceCompare || !priceCompare.length) return '';
  var cheapest = priceCompare[0];
  var rows = priceCompare.map(function(r) {
    var cls = 'compare-row';
    if (r.modelId === modelId) cls += ' active';
    if (r.modelId === cheapest.modelId) cls += ' cheapest';
    return '<div class="' + cls + '">' +
      '<span class="compare-label" title="' + r.label + '">' + r.label + '</span>' +
      '<span class="compare-rate">$' + r.inputCostPerMTok.toFixed(2) + '/$' + r.outputCostPerMTok.toFixed(2) + '</span>' +
      '<span class="compare-total">' + fmtCost(r.totalCost) + '</span>' +
      '</div>';
  }).join('');

  var syncClass = 'bundled';
  var syncText = 'bundled prices';
  if (catalogMeta) {
    if (catalogMeta.lastFetchError) {
      syncClass = 'error';
      syncText = 'sync failed';
    } else if (catalogMeta.source === 'remote') {
      var ageMs = catalogMeta.lastSyncAt ? Date.now() - new Date(catalogMeta.lastSyncAt).getTime() : 0;
      var ageDays = ageMs / 86400000;
      syncClass = ageDays > 7 ? 'stale' : 'fresh';
      syncText = 'synced ' + (catalogMeta.lastSyncAt ? formatTimeAgo(catalogMeta.lastSyncAt) : '');
    }
  }

  return '<div class="compare-box">' +
    '<div class="compare-header">' +
    '<span class="compare-title">Price Compare (this turn)</span>' +
    '<span class="compare-sync ' + syncClass + '">' +
    '<span class="sync-dot"></span>' + syncText +
    '<button class="compare-refresh" data-action="refreshPricing">Refresh</button>' +
    '</span>' +
    '</div>' +
    '<div class="compare-table">' + rows + '</div>' +
    '<div class="compare-note">Sorted by total cost. Active model highlighted. Output assumed at 25% of max for each model.</div>' +
    '</div>';
})()}

