  border-top: 1px solid var(--border);
  padding-top: 10px;
}
.section-title {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--desc-fg);
  margin-bottom: 8px;
}

.tab-list { list-style: none; }
.tab-item {
  display: flex;
  align-items: center;
  padding: 5px 6px;
  border-radius: 4px;
  cursor: pointer;
  gap: 8px;
  font-size: 12px;
}
.tab-item:hover { background: var(--list-hover); }
.tab-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}
.tab-dot.high { background: var(--low); opacity: 0.9; }
.tab-dot.med { background: var(--medium); opacity: 0.9; }
.tab-dot.low { background: var(--high); opacity: 0.9; }
.tab-name {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.tab-name.active { font-weight: 600; }
.tab-tokens { font-size: 11px; color: var(--fg); opacity: 0.8; }
.tab-actions {
  display: flex;
  gap: 2px;
}
.tab-actions button {
  background: none;
  border: none;
  color: var(--fg);
  cursor: pointer;
  font-size: 12px;
  padding: 2px 5px;
  border-radius: 3px;
}
.tab-actions button:hover { background: var(--list-hover); }

.action-btn {
  background: var(--btn-bg);
  color: var(--btn-fg);
  border: none;
  padding: 6px 12px;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  width: 100%;
  margin-top: 8px;
  transition: background 0.1s;
}
.action-btn:hover { background: var(--btn-hover); }
.action-btn.secondary {
  background: var(--card-bg);
  color: var(--fg);
  border: 1px solid var(--border);
}
.action-btn.secondary:hover {
  background: var(--list-hover);
}

.notes {
  font-size: 12px;
  color: var(--fg);
  margin-top: 8px;
}
.notes li { margin-bottom: 4px; }

.empty { text-align: center; color: var(--desc-fg); padding: 20px; font-size: 12px; }

.model-selector {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 10px;
  padding: 0 2px;
}
.model-selector label {
  font-size: 12px;
  color: var(--fg);
  white-space: nowrap;
}
.model-selector select {
  flex: 1;
  background: var(--input-bg);
  color: var(--input-fg);
  border: 1px solid var(--input-border);
  border-radius: 4px;
  padding: 4px 6px;
  font-size: 11px;
  cursor: pointer;
  outline: none;

