583	    function fmtTokens(n) {
584	      if (n >= 1000000) return (n / 1000000).toFixed(1) + 'M';
585	      if (n >= 1000) return (n / 1000).toFixed(1) + 'K';
586	      return n.toString();
587	    }
588	
589	    function formatTimeAgo(iso) {
590	      var ms = Date.now() - new Date(iso).getTime();
591	      var mins = Math.floor(ms / 60000);
592	      if (mins < 60) return mins + 'm ago';
593	      var hours = Math.floor(mins / 60);
594	      if (hours < 24) return hours + 'h ago';
595	      var days = Math.floor(hours / 24);
596	      return days + 'd ago';
597	    }
598	
599	    function fmtCost(n) {
600	      if (n < 0.001) return '<$0.001';
601	      if (n < 0.01) return '$' + n.toFixed(4);
602	      if (n < 1) return '$' + n.toFixed(3);
603	      return '$' + n.toFixed(2);
604	    }
605	
606	    function relClass(score) {
607	      if (score >= 0.6) return 'high';
608	      if (score >= 0.3) return 'med';
