623	        '<option value="' + m.id + '"' + (m.id === modelId ? ' selected' : '') + '>' + m.label + ' (' + fmtTokens(m.contextWindow) + ' | $' + m.inputCostPerMTok + '/$' + m.outputCostPerMTok + ')' + '</option>'
624	      ).join('');
625	
626	      app.innerHTML = \`
