640	              <span class="last-session-stat">\${lastSession.totalTurns} turns</span>
641	              <span class="last-session-stat">peak \${fmtTokens(lastSession.peakTokens)}</span>
642	              <span class="last-session-stat">\${lastSession.tabCount} tabs</span>
643	            </div>
644	          </div>
645	        \` : ''}
646	
647	        <div class="model-selector">
648	          <label>Model</label>
