667	              <span class="cost-value">\${fmtCost(costEstimate.inputCost)}</span>
668	              <span class="cost-label">Output (max)</span>
669	              <span class="cost-tokens">~\${fmtTokens(costEstimate.outputTokens)}</span>
670	              <span class="cost-value">\${fmtCost(costEstimate.outputCost)}</span>
671	              <div class="cost-sep"></div>
