722	          var sysPct = Math.round(((budgetBreakdown.systemPrompt + budgetBreakdown.instructions) / total) * 100);
723	          var convPct = Math.round((budgetBreakdown.conversation / total) * 100);
724	          var outPct = Math.round((budgetBreakdown.outputReservation / total) * 100);
725	          return '<div class="section">' +
726	            '<div class="section-title">Budget Breakdown</div>' +
727	            '<div class="breakdown-grid">' +
728	            '<span class="breakdown-label">Files</span>' +
729	            '<span class="breakdown-value">~' + fmtTokens(budgetBreakdown.files) + '</span>' +
730	            '<span class="breakdown-label">System</span>' +
731	            '<span class="breakdown-value">~' + fmtTokens(budgetBreakdown.systemPrompt) + '</span>' +
732	            '<span class="breakdown-label">Instructions</span>' +
733	            '<span class="breakdown-value">~' + fmtTokens(budgetBreakdown.instructions) + '</span>' +
734	            '<span class="breakdown-label">Conversation</span>' +
735	            '<span class="breakdown-value">~' + fmtTokens(budgetBreakdown.conversation) + '</span>' +
736	            '<span class="breakdown-label">Output reserve</span>' +
737	            '<span class="breakdown-value">~' + fmtTokens(budgetBreakdown.outputReservation) + '</span>' +
738	            '</div>' +
739	            '<div class="breakdown-bar">' +
740	            '<div style="display:flex;height:100%">' +
741	            '<div class="breakdown-bar-fill files" style="width:' + filesPct + '%"></div>' +
742	            '<div class="breakdown-bar-fill system" style="width:' + sysPct + '%"></div>' +
