744	            '<div class="breakdown-bar-fill output" style="width:' + outPct + '%"></div>' +
745	            '</div>' +
746	            '</div>' +
747	            '</div>';
748	        })()}
749	
750	        \${turnHistory && turnHistory.length > 0 ? \`
751	          <div class="section">
752	            <div class="section-title">Context Growth (\${turnHistory.length} turns)</div>
753	            <div class="growth-bars">
754	              \${turnHistory.map(function(t) {
755	                var pct = Math.max(5, Math.round((t.inputTokens / windowCapacity) * 100));
