757	              }).join('')}
758	            </div>
759	            <div class="growth-label">
760	              <span>T1: ~\${fmtTokens(turnHistory[0].inputTokens)}</span>
761	              <span>T\${turnHistory[turnHistory.length-1].turn}: ~\${fmtTokens(turnHistory[turnHistory.length-1].inputTokens)}</span>
762	            </div>
763	            \${turnHistory.length >= 2 ? '<div class="suggestion">+' + fmtTokens(Math.round((turnHistory[turnHistory.length-1].inputTokens - turnHistory[0].inputTokens) / (turnHistory.length-1))) + '/turn avg growth</div>' : ''}
764	          </div>
765	        \` : ''}
766	
767	        <div class="section">
768	          <div class="section-title">Files (\${relevant.length})</div>
769	          <ul class="tab-list">
770	            \${relevant.length === 0 ? '<li class="empty">No files open</li>' :
771	              relevant.map(t => renderTab(t)).join('')}
772	          </ul>
