786	
787	        <ul class="notes">
788	          \${healthReasons.map(r => '<li>' + r + '</li>').join('')}
789	        </ul>
790	
791	        \${chatTurnCount > 0 ? '<button class="action-btn secondary" data-action="resetTurns">Reset Turn Counter</button>' : ''}
792	      \`;
793	    }
794	
795	    function renderTab(t) {
796	      var safeUri = encodeURIComponent(t.uri);
797	      var pinBtn = t.isPinned
798	        ? '<button title="Unpin" data-action="unpin" data-uri="' + safeUri + '">\u{1F4CC}</button>'
